/**
 * @distilled.cloud/azure -- Azure SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the per-service
 * Smithy models that `scripts/convert.ts` converts from the
 * azure-rest-api-specs mirror: latest stable api-version per
 * `Microsoft.*` resource provider, plus one module per data-plane group such
 * as `keyvault-secrets` or `storage-blob`. Everything else in this folder is
 * hand-written.
 *
 * @example
 * ```ts
 * import * as Azure from "@distilled.cloud/azure";
 *
 * const groups = yield* Azure.resources.ResourceGroupsList({});
 * ```
 *
 * @example Data plane
 * ```ts
 * import * as secrets from "@distilled.cloud/azure/keyvault-secrets";
 *
 * const secret = yield* secrets.GetSecret({
 *   vaultBaseUrl: "https://my-vault.vault.azure.net",
 *   secretName: "db-password",
 *   secretVersion: "",
 * });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { AzureProtocol, type AzureOpError, type AzureOpContext } from "./protocol.ts";
export * as Retry from "./retry.ts";
export * from "./services/index.ts";
